package com.utegear.entity;
import jakarta.persistence.*;
@Entity @Table(name="product_images") public class ProductImage { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(name="secure_url",nullable=false,length=500) private String secureUrl; @Column(name="public_id",nullable=false,unique=true,length=255) private String publicId; @Column(name="alt_text",length=255) private String altText; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(name="is_primary",nullable=false) private boolean primary; protected ProductImage(){} public ProductImage(String secureUrl,String publicId,String altText,int sortOrder,boolean primary){this.secureUrl=secureUrl;this.publicId=publicId;this.altText=altText;this.sortOrder=sortOrder;this.primary=primary;} void attach(Product product){this.product=product;} public Long getId(){return id;} public String getSecureUrl(){return secureUrl;} public String getPublicId(){return publicId;} public String getAltText(){return altText;} public int getSortOrder(){return sortOrder;} public boolean isPrimary(){return primary;} }
